/*
 * bundle.js — produce the self-contained combined-instrument JS for Max.
 * Run: node thelmic/devices/tools/bundle.js
 *
 * Concatenates field-osc-config.js + onset-engine.js + instrument-glue.js into
 * one file with NO require()/exports, so the combined instrument device loads
 * as a single [js] object with no module search-path dependency. The physics
 * stays canonical (onset-engine.js) — this is a mechanical inline, not a copy.
 *
 * Stripping rules (line-based, deliberately conservative):
 *   - drop lines that are `var X = require("...");`
 *   - drop lines that start with `exports.` or `module.exports`
 * Everything else (top-level function/var declarations) survives and lands in
 * the shared Max js global scope, which is exactly what the glue references.
 */

var fs = require("fs");
var path = require("path");

var SRC = path.join(__dirname, "..", "src");
var OUT = path.join(__dirname, "..", "thelmic.pulse-field-instrument.bundle.js");

var DEPS = ["field-osc-config.js", "onset-engine.js", "instrument-glue.js"];

function strip(code) {
    return code.split("\n").filter(function (line) {
        var t = line.trim();
        if (/^var\s+\w+\s*=\s*require\(/.test(t)) { return false; }
        if (/^exports\./.test(t)) { return false; }
        if (/^module\.exports/.test(t)) { return false; }
        return true;
    }).join("\n");
}

var header =
    "/* GENERATED by tools/bundle.js — do not edit.\n" +
    " * Self-contained Pulse Field combined instrument (Stage 0 + Stage 1).\n" +
    " * Source of truth: src/field-osc-config.js, src/onset-engine.js,\n" +
    " * src/instrument-glue.js. Regenerate with: node tools/bundle.js\n" +
    " */\n\n";

var parts = [header];
DEPS.forEach(function (name) {
    var code = fs.readFileSync(path.join(SRC, name), "utf8");
    parts.push("// ===== " + name + " =====\n" + strip(code) + "\n");
});

fs.writeFileSync(OUT, parts.join("\n"));
console.log("wrote " + path.basename(OUT));
